export const products: Product[] = catalogSeeds.map(({variants, sizes, heights, ...rest}) => {
 const readableDescription = readableDescriptions[rest.slug];
 return {...rest, sizes: sizeSets[sizes], heights: heightSets[heights], variantPrices: variants.map(([sizeId,heightId,price])=>({sizeId,heightId,price,originalPrice:price})), readableDescription, description: [readableDescription.intro, ...readableDescription.points].join(" "), rating:0, reviewsCount:0, stock:1, discountPercent:0, warrantyYears:rest.category === "mattresses" ? 10 : 0};
});

export function getProductBySlug(slug: string): Product | undefined {
  return products.find((p) => p.slug === slug);
}

export function getProductsByCategory(category: CategorySlug): Product[] {
  return products.filter((p) => p.category === category);
}

export function getFeaturedProducts(): Product[] {
  return products.filter((p) => p.isFeatured);
}




export const springTypesList: SpringType[] = ["سوست متصلة", "سوست منفصلة", "فوم", "إسفنج مضغوط", "مراتب بدون سوست", "مراتب رول", "مراتب متصلة (أمريكي)", "مراتب متصلة ألماني", "مراتب منفصلة(بوكيت)"];

export const firmnessList: Firmness[] = [];

// الارتفاعات والمقاسات للفلاتر: مراتب وطبقات التطرية فقط (اختيارات الإكسسوارات لا تصلح فلاتر عامة)
const filterProducts = products.filter((p) => p.category === "mattresses" || p.category === "toppers");

export const allHeightsList = Array.from(
  new Map(filterProducts.flatMap((p) => p.heights).map((h) => [h.id, h])).values()
);

export const allSizesList = Array.from(
  new Map(filterProducts.flatMap((p) => p.sizes).map((s) => [s.id, s])).values()
);

// لا توجد تقييمات معروضة حالياً — لا نعرض آراء غير حقيقية
// وصف مختصر تلقائي للمنتجات اللي وصفها كان مجرد اسمها — من حقائق الكتالوج نفسه (ماركة/نوع/ضمان) بدون أي مواصفات جديدة
const categoryLabel: Record<string, string> = { mattresses: "مرتبة", pillows: "مخدة", protectors: "واقي مرتبة", toppers: "طبقة تطرية (توب)" };
products.forEach((p) => {
  if (p.shortDescription.trim() !== p.name.trim()) return;
  const brand = p.specs.find((s) => s.label === "الماركة")?.value;
  const brandPart = brand ? ` ${brand}` : "";
  const springPart = p.category === "mattresses" && p.springType ? ` ب${p.springType}` : "";
  const warrantyPart = p.category === "mattresses" ? "، وضمان ١٠ سنين" : "";
  const feminine = p.category !== "protectors";
  p.shortDescription = `${categoryLabel[p.category] ?? "منتج"}${brandPart}${springPart}، بمقاسات واختيارات متعددة${warrantyPart}.`;
});

export const testimonials: { name: string; location: string; rating: number; comment: string }[] = [];

